/* fx.h -- growable strings and a streaming FASTA/FASTQ record reader.
 *
 * The reader is deliberately byte-exact about a number of quirks that the
 * reference tool exposes: leading garbage before the first header is skipped,
 * blank lines inside a sequence are dropped, a stray '+' turns a FASTA record
 * into a FASTQ one, quality lines are concatenated until they are at least as
 * long as the sequence, and a record whose quality length does not match the
 * sequence length aborts the stream.
 */
#ifndef SEQKIT_FX_H
#define SEQKIT_FX_H

#include <stddef.h>
#include <zlib.h>

/* ---------- growable string ---------- */

typedef struct {
	size_t len, cap;
	char *s;
} str_t;

void str_grow(str_t *b, size_t need);   /* make room for `need` more bytes + NUL */
void str_putc(str_t *b, int c);
void str_putsn(str_t *b, const char *p, size_t n);
void str_puts(str_t *b, const char *p);
void str_free(str_t *b);
/* Always safe to print: returns "" for a never-used buffer. */
const char *str_cstr(const str_t *b);

/* ---------- record reader ---------- */

#define FX_BUFSZ 16384

typedef struct {
	gzFile fp;
	unsigned char *buf;
	int begin, end;
	int eof;
	int hdr;              /* header char held over from the previous record */
} fxin_t;

typedef struct {
	str_t name, comment, seq, qual;
} fxrec_t;

/* fn == NULL or "-" reads standard input.  Returns NULL if the file could not
 * be opened. */
fxin_t *fx_open(const char *fn);
void fx_close(fxin_t *f);

void fx_rec_init(fxrec_t *r);
void fx_rec_free(fxrec_t *r);

/* Returns the sequence length (>= 0) on success, -1 at end of stream,
 * -2 when the quality string does not match the sequence, -3 on read error. */
long fx_read(fxin_t *f, fxrec_t *r);

#endif

