#include <ctype.h>
#include <stdlib.h>
#include <string.h>

#include "fx.h"

/* ---------- growable string ---------- */

void str_grow(str_t *b, size_t need)
{
	size_t want = b->len + need + 1;
	if (want <= b->cap) return;
	if (b->cap == 0) b->cap = 64;
	while (b->cap < want) b->cap <<= 1;
	b->s = (char *)realloc(b->s, b->cap);
	if (b->s == NULL) abort();
}

void str_putc(str_t *b, int c)
{
	str_grow(b, 1);
	b->s[b->len++] = (char)c;
	b->s[b->len] = '\0';
}

void str_putsn(str_t *b, const char *p, size_t n)
{
	str_grow(b, n);
	if (n) memcpy(b->s + b->len, p, n);
	b->len += n;
	b->s[b->len] = '\0';
}

void str_puts(str_t *b, const char *p) { str_putsn(b, p, strlen(p)); }

void str_free(str_t *b)
{
	free(b->s);
	b->s = NULL;
	b->len = b->cap = 0;
}

const char *str_cstr(const str_t *b) { return b->s ? b->s : ""; }

/* ---------- low level stream ---------- */

fxin_t *fx_open(const char *fn)
{
	gzFile fp;
	fxin_t *f;
	if (fn == NULL || (fn[0] == '-' && fn[1] == '\0')) fp = gzdopen(0, "r");
	else fp = gzopen(fn, "r");
	if (fp == NULL) return NULL;
	f = (fxin_t *)calloc(1, sizeof(fxin_t));
	f->fp = fp;
	f->buf = (unsigned char *)malloc(FX_BUFSZ);
	return f;
}

void fx_close(fxin_t *f)
{
	if (f == NULL) return;
	gzclose(f->fp);
	free(f->buf);
	free(f);
}

void fx_rec_init(fxrec_t *r)
{
	memset(r, 0, sizeof(fxrec_t));
	/* Give every field a buffer so that callers may always read the C string. */
	str_grow(&r->name, 0);    r->name.s[0] = '\0';
	str_grow(&r->comment, 0); r->comment.s[0] = '\0';
	str_grow(&r->seq, 0);     r->seq.s[0] = '\0';
	str_grow(&r->qual, 0);    r->qual.s[0] = '\0';
}

void fx_rec_free(fxrec_t *r)
{
	str_free(&r->name);
	str_free(&r->comment);
	str_free(&r->seq);
	str_free(&r->qual);
}

static int fx_refill(fxin_t *f)
{
	if (f->eof) return 0;
	f->begin = 0;
	f->end = gzread(f->fp, f->buf, FX_BUFSZ);
	if (f->end == 0) { f->eof = 1; return 0; }
	if (f->end < 0) { f->eof = 1; f->end = 0; return -1; }
	return 1;
}

static int fx_getc(fxin_t *f)
{
	if (f->begin >= f->end && fx_refill(f) <= 0) return -1;
	return f->buf[f->begin++];
}

#define FX_SEP_SPACE 0
#define FX_SEP_LINE  1

/* Copy bytes up to the next separator into `s`.  Returns the resulting total
 * length, -1 when nothing at all could be read at end of stream, or -3 on a
 * decompression/read failure.  A trailing CR of a line is discarded, but only
 * when it is not the sole byte of the accumulated string -- that asymmetry is
 * observable in the reference tool. */
static long fx_getuntil(fxin_t *f, int sep, str_t *s, int *sepout, int append)
{
	int gotany = 0;
	if (sepout) *sepout = 0;
	if (!append) s->len = 0;
	for (;;) {
		int i;
		if (f->begin >= f->end) {
			int rc;
			if (f->eof) break;
			rc = fx_refill(f);
			if (rc == 0) break;
			if (rc < 0) return -3;
		}
		if (sep == FX_SEP_LINE) {
			unsigned char *p = (unsigned char *)memchr(f->buf + f->begin, '\n', (size_t)(f->end - f->begin));
			i = p ? (int)(p - f->buf) : f->end;
		} else {
			for (i = f->begin; i < f->end; ++i)
				if (isspace(f->buf[i])) break;
		}
		str_putsn(s, (char *)f->buf + f->begin, (size_t)(i - f->begin));
		gotany = 1;
		f->begin = i + 1;
		if (i < f->end) {
			if (sepout) *sepout = f->buf[i];
			break;
		}
	}
	if (!gotany && f->eof) return -1;
	str_grow(s, 0);
	if (sep == FX_SEP_LINE && s->len > 1 && s->s[s->len - 1] == '\r') --s->len;
	s->s[s->len] = '\0';
	return (long)s->len;
}

long fx_read(fxin_t *f, fxrec_t *r)
{
	int c;
	long rc;

	if (f->hdr == 0) {                     /* find the next header line */
		while ((c = fx_getc(f)) >= 0 && c != '>' && c != '@')
			;
		if (c < 0) return -1;
		f->hdr = c;
	}
	r->comment.len = r->seq.len = r->qual.len = 0;
	r->comment.s[0] = r->seq.s[0] = r->qual.s[0] = '\0';

	rc = fx_getuntil(f, FX_SEP_SPACE, &r->name, &c, 0);
	if (rc < 0) return rc;
	if (c != '\n') fx_getuntil(f, FX_SEP_LINE, &r->comment, NULL, 0);

	while ((c = fx_getc(f)) >= 0 && c != '>' && c != '+' && c != '@') {
		if (c == '\n') continue;           /* blank line */
		str_putc(&r->seq, c);
		fx_getuntil(f, FX_SEP_LINE, &r->seq, NULL, 1);
	}
	if (c == '>' || c == '@') f->hdr = c;
	str_grow(&r->qual, r->seq.len);
	r->qual.s[r->seq.len] = '\0';
	if (c != '+') return (long)r->seq.len; /* FASTA */

	while ((c = fx_getc(f)) >= 0 && c != '\n')
		;                                  /* discard the rest of the '+' line */
	if (c < 0) return -2;
	while ((rc = fx_getuntil(f, FX_SEP_LINE, &r->qual, NULL, 1)) >= 0 && r->qual.len < r->seq.len)
		;
	f->hdr = 0;
	if (r->seq.len != r->qual.len) return -2;
	return (long)r->seq.len;
