#include "util.h"

/* ---------- MT19937-64 ---------- */

#define MT_M 156
#define MT_MATRIX_A 0xB5026F5AA96619E9ULL
#define MT_UPPER 0xFFFFFFFF80000000ULL
#define MT_LOWER 0x7FFFFFFFULL

void mt_seed(mt_t *m, uint64_t seed)
{
	int i;
	m->mt[0] = seed;
	for (i = 1; i < MT_N; ++i)
		m->mt[i] = 6364136223846793005ULL * (m->mt[i - 1] ^ (m->mt[i - 1] >> 62)) + (uint64_t)i;
	m->idx = MT_N;
}

uint64_t mt_u64(mt_t *m)
{
	static const uint64_t mag[2] = { 0ULL, MT_MATRIX_A };
	uint64_t x;
	if (m->idx >= MT_N) {                      /* regenerate the whole block */
		int i;
		for (i = 0; i < MT_N - MT_M; ++i) {
			x = (m->mt[i] & MT_UPPER) | (m->mt[i + 1] & MT_LOWER);
			m->mt[i] = m->mt[i + MT_M] ^ (x >> 1) ^ mag[(int)(x & 1ULL)];
		}
		for (; i < MT_N - 1; ++i) {
			x = (m->mt[i] & MT_UPPER) | (m->mt[i + 1] & MT_LOWER);
			m->mt[i] = m->mt[i + (MT_M - MT_N)] ^ (x >> 1) ^ mag[(int)(x & 1ULL)];
		}
		x = (m->mt[MT_N - 1] & MT_UPPER) | (m->mt[0] & MT_LOWER);
		m->mt[MT_N - 1] = m->mt[MT_M - 1] ^ (x >> 1) ^ mag[(int)(x & 1ULL)];
		m->idx = 0;
	}
	x = m->mt[m->idx++];
	x ^= (x >> 29) & 0x5555555555555555ULL;
	x ^= (x << 17) & 0x71D67FFFEDA60000ULL;
	x ^= (x << 37) & 0xFFF7EEE000000000ULL;
	x ^= (x >> 43);
	return x;
}

double mt_real(mt_t *m) { return (double)(mt_u64(m) >> 11) * (1.0 / 9007199254740992.0); }

/* ---------- input ---------- */

fxin_t *open_in(const char *fn, const char *cmd)
{
	fxin_t *f = fx_open(fn);
	if (f == NULL)
		fprintf(stderr, "[E::stk_%s] failed to open the input file/stream.\n", cmd);
	return f;
}

int want_usage(int argc, char *argv[], int optind_)
