struct hnode {
	char *key;
	long val;
	hnode_t *next;
};

static size_t str_hash(const char *s)
{
	size_t h = 5381;
	while (*s) h = h * 33 + (unsigned char)*s++;
	return h;
}

ivset_t *ivset_init(void)
{
	ivset_t *s = (ivset_t *)calloc(1, sizeof(ivset_t));
	s->nbucket = 1024;
	s->bucket = (hnode_t **)calloc(s->nbucket, sizeof(hnode_t *));
	return s;
}

void ivset_free(ivset_t *s)
{
	size_t i;
	if (s == NULL) return;
	for (i = 0; i < s->nbucket; ++i) {
		hnode_t *p = s->bucket[i];
		while (p) { hnode_t *q = p->next; free(p->key); free(p); p = q; }
	}
	free(s->bucket);
	for (i = 0; i < s->n; ++i) { free(s->a[i].name); free(s->a[i].iv); }
	free(s->a);
	free(s);
}

static void ivset_rehash(ivset_t *s)
{
	size_t old = s->nbucket, i;
	hnode_t **ob = s->bucket;
	s->nbucket = old << 1;
	s->bucket = (hnode_t **)calloc(s->nbucket, sizeof(hnode_t *));
	for (i = 0; i < old; ++i) {
		hnode_t *p = ob[i];
		while (p) {
			hnode_t *q = p->next;
			size_t b = str_hash(p->key) & (s->nbucket - 1);
			p->next = s->bucket[b];
			s->bucket[b] = p;
			p = q;
		}
	}
	free(ob);
}

long ivset_get(ivset_t *s, const char *name, int create)
{
	size_t b = str_hash(name) & (s->nbucket - 1);
	hnode_t *p;
	for (p = s->bucket[b]; p; p = p->next)
		if (strcmp(p->key, name) == 0) return p->val;
	if (!create) return -1;
	if (s->n == s->m) {
		s->m = s->m ? s->m << 1 : 16;
		s->a = (ivseq_t *)realloc(s->a, s->m * sizeof(ivseq_t));
	}
	memset(&s->a[s->n], 0, sizeof(ivseq_t));
	s->a[s->n].name = strdup(name);
	p = (hnode_t *)calloc(1, sizeof(hnode_t));
	p->key = strdup(name);
	p->val = (long)s->n++;
	p->next = s->bucket[b];
	s->bucket[b] = p;
	if (s->n > s->nbucket) ivset_rehash(s);
	return p->val;
}

