/* util.h -- shared helpers: 64-bit Mersenne Twister, input opening, and the
 * name/interval container used by the region-aware subcommands. */
#ifndef SEQKIT_UTIL_H
#define SEQKIT_UTIL_H

#include <stddef.h>
#include <stdint.h>

#include "fx.h"

/* ---------- MT19937-64 ---------- */

#define MT_N 312

typedef struct {
	uint64_t mt[MT_N];
	int idx;
} mt_t;

void mt_seed(mt_t *m, uint64_t seed);
uint64_t mt_u64(mt_t *m);
/* Uniform in [0,1) with 53 bits of resolution. */
double mt_real(mt_t *m);

/* ---------- input ---------- */

/* Opens `fn` (NULL or "-" meaning stdin).  On failure prints
 * "[E::stk_<cmd>] failed to open the input file/stream." to stderr and returns NULL. */
fxin_t *open_in(const char *fn, const char *cmd);
/* True when no filename was supplied and stdin is a terminal, i.e. the point at
 * which the reference tool prints its usage instead of blocking on the console. */
int want_usage(int argc, char *argv[], int optind_);

/* Emulates the exact text glibc's assert() writes before aborting, so that the
 * few internal consistency checks of the reference tool stay observable. */
void assert_fail(const char *file, int line, const char *func, const char *expr) __attribute__((noreturn));

/* ---------- intervals grouped by sequence name ---------- */

typedef struct {
	int64_t beg, end;
} iv_t;

typedef struct {
	char *name;
	iv_t *iv;
	size_t n, m;
} ivseq_t;

typedef struct hnode hnode_t;

typedef struct {
	ivseq_t *a;
	size_t n, m;
	hnode_t **bucket;
	size_t nbucket;
} ivset_t;

ivset_t *ivset_init(void);
void ivset_free(ivset_t *s);
/* Returns the index of `name`, creating it when `create` is non-zero, else -1. */
long ivset_get(ivset_t *s, const char *name, int create);
void ivset_add(ivset_t *s, const char *name, int64_t beg, int64_t end);

/* Reads a BED-like/name-list file: lines with >= 2 fields where fields 2 (and 3)
 * parse as numbers become intervals, a bare name means the whole sequence
 * (interval [0, INT64_MAX)).  Returns NULL when the file cannot be read. */
ivset_t *ivset_read(const char *fn);

/* ---------- nucleotides ---------- */

